"""Synthetic training set generated by running the deterministic engine.

The ML model is a *surrogate* (emulator) of the scientific engine: it learns
the mapping from scenario parameters to the engine's horizon outputs. Every
label is produced by the engine itself, so the dataset is fully reproducible
(fixed seed) and needs no external data source.

The generator is pure (no database, no I/O), which keeps it unit-testable and
safe to run inside the hermetic test suite.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Optional

import numpy as np

from app.models.scenario import SeaLevelRise
from app.simulations.engine import run_simulation

# Input features, in the exact order the model expects them.
FEATURE_NAMES: list[str] = [
    "restoration_level",
    "sea_level_rise",
    "horizon_year",
    "baseline_area_ha",
    "baseline_carbon_density",
]

SLR_ENCODING: dict[SeaLevelRise, float] = {
    SeaLevelRise.LOW: 0.0,
    SeaLevelRise.MEDIUM: 1.0,
    SeaLevelRise.HIGH: 2.0,
}
_SLR_BY_CODE: dict[float, SeaLevelRise] = {code: slr for slr, code in SLR_ENCODING.items()}

DEFAULT_SEED = 42
DEFAULT_N_SAMPLES = 8000

# Sampling ranges for the generated scenarios.
_RESTORATION_RANGE = (0.0, 100.0)
_HORIZON_RANGE = (2030, 2100)
_AREA_RANGE = (50.0, 300.0)
_DENSITY_RANGE = (50.0, 120.0)


@dataclass
class TrainingData:
    """Feature matrix plus the engine labels used to supervise the models."""

    X: np.ndarray                  # shape (n_samples, n_features)
    y_regression: np.ndarray       # shape (n_samples, 2): [variation_pct, horizon_carbon]
    y_meets: np.ndarray            # shape (n_samples,): 0/1 hypothesis label
    feature_names: list[str]

    @property
    def n_samples(self) -> int:
        return int(self.X.shape[0])


def _decode_slr(code: float) -> SeaLevelRise:
    return _SLR_BY_CODE[float(code)]


def generate_dataset(
    n_samples: int = DEFAULT_N_SAMPLES,
    seed: int = DEFAULT_SEED,
    params: Optional[dict[str, float]] = None,
) -> TrainingData:
    """Run the engine over a randomized grid of scenarios to build a dataset.

    ``params`` allows overriding the engine calibration parameters, so the
    surrogate can mirror a custom calibration loaded from ``model_params``.
    """
    if n_samples <= 0:
        raise ValueError("n_samples debe ser mayor que cero")

    rng = np.random.default_rng(seed)
    restoration = rng.uniform(*_RESTORATION_RANGE, n_samples)
    slr_codes = rng.integers(0, 3, n_samples).astype(float)
    horizon = rng.integers(_HORIZON_RANGE[0], _HORIZON_RANGE[1] + 1, n_samples)
    area = rng.uniform(*_AREA_RANGE, n_samples)
    density = rng.uniform(*_DENSITY_RANGE, n_samples)

    X = np.column_stack([restoration, slr_codes, horizon, area, density])
    y_variation = np.empty(n_samples, dtype=float)
    y_carbon = np.empty(n_samples, dtype=float)
    y_meets = np.empty(n_samples, dtype=np.int64)

    for i in range(n_samples):
        result = run_simulation(
            restoration_level=float(restoration[i]),
            sea_level_rise=_decode_slr(slr_codes[i]),
            horizon_year=int(horizon[i]),
            baseline_area_ha=float(area[i]),
            baseline_carbon_density=float(density[i]),
            params=params,
        )
        y_variation[i] = result["horizon_variation_pct"]
        y_carbon[i] = result["horizon_carbon"]
        y_meets[i] = 1 if result["meets_hypothesis"] else 0

    return TrainingData(
        X=X,
        y_regression=np.column_stack([y_variation, y_carbon]),
        y_meets=y_meets,
        feature_names=list(FEATURE_NAMES),
    )
